SET statement_timeout = 0;
SET lock_timeout = 0;
SET idle_in_transaction_session_timeout = 0;
SET client_encoding = 'UTF8';
SET standard_conforming_strings = on;
SELECT pg_catalog.set_config('search_path', '', false);
SET check_function_bodies = false;
SET xmloption = content;
SET client_min_messages = warning;
SET row_security = off;

COMMENT ON SCHEMA "public" IS 'standard public schema';

CREATE EXTENSION IF NOT EXISTS "pg_graphql" WITH SCHEMA "graphql";

CREATE EXTENSION IF NOT EXISTS "pg_stat_statements" WITH SCHEMA "extensions";

CREATE EXTENSION IF NOT EXISTS "pgcrypto" WITH SCHEMA "extensions";

CREATE EXTENSION IF NOT EXISTS "postgis" WITH SCHEMA "public";

CREATE EXTENSION IF NOT EXISTS "supabase_vault" WITH SCHEMA "vault";

CREATE EXTENSION IF NOT EXISTS "uuid-ossp" WITH SCHEMA "extensions";

CREATE OR REPLACE FUNCTION "public"."can_citizen_see_recycler"("r_profile_id" "uuid", "citizen_id" "uuid") RETURNS boolean
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT EXISTS (
    SELECT 1 FROM public.recyclable_material_listings l
    JOIN public.recycler_pickups p ON p.listing_id = l.id
    WHERE p.recycler_id = r_profile_id AND l.owner_id = citizen_id
  );
$$;

ALTER FUNCTION "public"."can_citizen_see_recycler"("r_profile_id" "uuid", "citizen_id" "uuid") OWNER TO "postgres";

CREATE OR REPLACE FUNCTION "public"."cancel_recycler_pickup"("p_pickup_id" "uuid") RETURNS json
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'auth'
    AS $$
DECLARE
  v_user_id uuid := auth.uid();
  v_pickup record;
  v_owner_id uuid;
BEGIN
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Usuario no autenticado.';
  END IF;

  SELECT * INTO v_pickup
  FROM public.recycler_pickups
  WHERE id = p_pickup_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'La orden de recolección no existe.';
  END IF;

  SELECT owner_id INTO v_owner_id
  FROM public.recyclable_material_listings
  WHERE id = v_pickup.listing_id;

  IF v_user_id <> v_pickup.recycler_id AND v_user_id <> v_owner_id THEN
    RAISE EXCEPTION 'No tiene permisos para cancelar esta orden de recolección.';
  END IF;

  IF v_pickup.status <> 'pendiente' THEN
    RAISE EXCEPTION 'Solo se pueden cancelar recolecciones en estado pendiente (estado actual: %).', v_pickup.status;
  END IF;

  UPDATE public.recycler_pickups
  SET status = 'cancelado',
      cancelled_at = now()
  WHERE id = p_pickup_id;

  RETURN json_build_object(
    'success', true,
    'pickup_id', p_pickup_id,
    'listing_id', v_pickup.listing_id,
    'cancelled_at', now(),
    'message', 'Recolección cancelada exitosamente.'
  );
END;
$$;

ALTER FUNCTION "public"."cancel_recycler_pickup"("p_pickup_id" "uuid") OWNER TO "postgres";

CREATE OR REPLACE FUNCTION "public"."check_max_report_photos"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
BEGIN
  IF (SELECT count(*) FROM public.report_photos WHERE report_id = NEW.report_id) >= 3 THEN
    RAISE EXCEPTION 'Un reporte no puede contener más de 3 fotografías de evidencia.';
  END IF;
  RETURN NEW;
END;
$$;

ALTER FUNCTION "public"."check_max_report_photos"() OWNER TO "postgres";

CREATE OR REPLACE FUNCTION "public"."enforce_bulky_request_status_transition"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
BEGIN
  IF OLD.status IS DISTINCT FROM NEW.status THEN

    IF OLD.status = 'pendiente' AND NEW.status NOT IN ('cotizado', 'cancelado') THEN
      RAISE EXCEPTION 'Transición inválida: una solicitud "pendiente" solo puede pasar a "cotizado" o "cancelado".';
    
    ELSIF OLD.status = 'cotizado' AND NEW.status NOT IN ('programado', 'cancelado') THEN
      RAISE EXCEPTION 'Transición inválida: una solicitud "cotizada" solo puede pasar a "programado" o "cancelado".';
    
    ELSIF OLD.status = 'programado' AND NEW.status NOT IN ('recolectado', 'cancelado') THEN
      RAISE EXCEPTION 'Transición inválida: una solicitud "programada" solo puede pasar a "recolectado" o "cancelado".';
    
    ELSIF OLD.status IN ('recolectado', 'cancelado') THEN
      RAISE EXCEPTION 'La solicitud ya fue "%" y no se puede modificar.', OLD.status;
    END IF;

  END IF;

  RETURN NEW;
END;
$$;

ALTER FUNCTION "public"."enforce_bulky_request_status_transition"() OWNER TO "postgres";

CREATE OR REPLACE FUNCTION "public"."enforce_report_status_transition"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
BEGIN
  -- Validar solo cuando el campo status esté cambiando
  IF OLD.status IS DISTINCT FROM NEW.status THEN
    
    -- Reglas de transición desde 'pendiente'
    IF OLD.status = 'pendiente' AND NEW.status NOT IN ('aprobado', 'rechazado', 'duplicado') THEN
      RAISE EXCEPTION 'Transición no permitida: de "pendiente" solo se puede pasar a "aprobado", "rechazado" o "duplicado".';
    
    -- Reglas de transición desde 'aprobado'
    ELSIF OLD.status = 'aprobado' AND NEW.status NOT IN ('atendido') THEN
      RAISE EXCEPTION 'Transición no permitida: de "aprobado" solo se puede pasar a "atendido".';
    
    -- Estados terminales que no permiten más cambios
    ELSIF OLD.status IN ('rechazado', 'duplicado', 'atendido') THEN
      RAISE EXCEPTION 'El reporte ya se encuentra en un estado final ("%") y no puede ser modificado.', OLD.status;
    END IF;
  END IF;
  RETURN NEW;
END;
$$;

ALTER FUNCTION "public"."enforce_report_status_transition"() OWNER TO "postgres";

CREATE OR REPLACE FUNCTION "public"."get_my_roles"() RETURNS TABLE("role_code" "text", "label" "text", "description" "text", "is_active" boolean)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'auth'
    AS $$
DECLARE
  v_user_id uuid := auth.uid();
  v_active_role text;
BEGIN
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Usuario no autenticado.';
  END IF;

  SELECT COALESCE(p.active_role, p.role_code) INTO v_active_role FROM public.profiles p WHERE p.id = v_user_id;

  RETURN QUERY
  SELECT 
    r.code AS role_code,
    r.name AS label,
    r.description,
    (r.code = v_active_role) AS is_active
  FROM public.user_roles ur
  JOIN public.roles r ON r.code = ur.role_code
  WHERE ur.profile_id = v_user_id;
END;
$$;

ALTER FUNCTION "public"."get_my_roles"() OWNER TO "postgres";

CREATE OR REPLACE FUNCTION "public"."get_ranked_collection_points"("p_origin_location" "public"."geography" DEFAULT NULL::"public"."geography") RETURNS TABLE("point_id" "uuid", "label" "text", "neighborhood" "text", "location" "public"."geography", "approved_reports_count" bigint, "zone_density" bigint, "oldest_report_days" numeric, "distance_km" numeric, "priority_score" numeric)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'auth'
    AS $$
DECLARE
  v_company_id uuid;
  v_w1 numeric;
  v_w2 numeric;
  v_w3 numeric;
  v_w4 numeric;
BEGIN
  -- A. Identificar la empresa del operador que consulta
  SELECT company_id INTO v_company_id
  FROM operators
  WHERE profile_id = auth.uid();

  -- B. Obtener pesos configurados por la empresa
  SELECT w1, w2, w3, w4 INTO v_w1, v_w2, v_w3, v_w4
  FROM priority_weights
  WHERE company_id = v_company_id;

  -- Fallback normativo según IEEE 830: 30%, 30%, 25%, 15%
  IF NOT FOUND THEN
    v_w1 := 0.30; v_w2 := 0.30; v_w3 := 0.25; v_w4 := 0.15;
  END IF;

  -- C. Calcular puntaje ponderado de urgencia
  RETURN QUERY
  SELECT 
    v.point_id,
    v.label,
    v.neighborhood,
    v.location,
    v.approved_reports_count,
    v.zone_density,
    v.oldest_report_days,
    
    CASE 
      WHEN p_origin_location IS NOT NULL THEN (ST_Distance(v.location, p_origin_location) / 1000.0)::numeric
      ELSE 0
    END AS distance_km,
    
    (
      (v_w1 * v.approved_reports_count) + 
      (v_w2 * v.zone_density) + 
      (v_w3 * v.oldest_report_days) - 
      (v_w4 * (
        CASE 
          WHEN p_origin_location IS NOT NULL THEN (ST_Distance(v.location, p_origin_location) / 1000.0)
          ELSE 0
        END
      ))
    )::numeric AS priority_score

  FROM collection_points_priority_view v
  WHERE v.approved_reports_count > 0
  ORDER BY priority_score DESC;
END;
$$;

ALTER FUNCTION "public"."get_ranked_collection_points"("p_origin_location" "public"."geography") OWNER TO "postgres";

