CREATE OR REPLACE FUNCTION "public"."redeem_coupon"("p_coupon_id" "uuid") RETURNS json
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'auth'
    AS $$
DECLARE
  v_citizen_id uuid := auth.uid();
  v_coupon record;
  v_balance int;
  v_redemption_id uuid;
  v_code text;
BEGIN
  IF v_citizen_id IS NULL THEN
    RAISE EXCEPTION 'Usuario no autenticado.';
  END IF;

  -- A. Consultar cupón con bloqueo de fila para evitar sobreventas concurrentes
  SELECT * INTO v_coupon FROM coupons WHERE id = p_coupon_id FOR UPDATE;
  IF NOT FOUND OR NOT v_coupon.is_active THEN
    RAISE EXCEPTION 'El cupón no está disponible o no existe.';
  END IF;

  IF v_coupon.quantity_available <= 0 THEN
    RAISE EXCEPTION 'El cupón se ha agotado.';
  END IF;

  IF v_coupon.valid_until IS NOT NULL AND v_coupon.valid_until < CURRENT_DATE THEN
    RAISE EXCEPTION 'El cupón ha expirado.';
  END IF;

  -- B. Verificar saldo suficiente de EcoPuntos
  SELECT ecopoints_balance INTO v_balance FROM citizens WHERE profile_id = v_citizen_id;
  IF v_balance IS NULL OR v_balance < v_coupon.points_cost THEN
    RAISE EXCEPTION 'Saldo insuficiente de EcoPuntos.';
  END IF;

  -- C. Reducir stock del cupón
  UPDATE coupons 
  SET quantity_available = quantity_available - 1 
  WHERE id = p_coupon_id;

  -- D. Generar código legible único (ECO-XXXXXXXX)
  v_code := 'ECO-' || upper(substr(md5(random()::text || clock_timestamp()::text), 1, 8));

  -- E. Registrar la redención
  INSERT INTO coupon_redemptions (citizen_id, coupon_id, code, status)
  VALUES (v_citizen_id, p_coupon_id, v_code, 'emitido')
  RETURNING id INTO v_redemption_id;

  -- F. Registrar transacción negativa (El trigger sync_citizen_ecopoints_balance deduce el saldo)
  INSERT INTO ecopoints_transactions (citizen_id, points, reason_code, redemption_id)
  VALUES (v_citizen_id, -abs(v_coupon.points_cost), 'redencion_cupon', v_redemption_id);

  RETURN json_build_object(
    'success', true,
    'redemption_id', v_redemption_id,
    'code', v_code,
    'message', 'Cupón redimido exitosamente. Presenta este código en el comercio.'
  );
END;
$$;

ALTER FUNCTION "public"."redeem_coupon"("p_coupon_id" "uuid") OWNER TO "postgres";

CREATE OR REPLACE FUNCTION "public"."reserve_material_listing"("p_listing_id" "uuid") RETURNS json
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'auth'
    AS $$
DECLARE
  v_recycler_id uuid := auth.uid();
  v_listing record;
  v_pickup_id uuid;
  v_qr_code text;
  v_expires_at timestamptz := now() + interval '24 hours';
BEGIN
  IF v_recycler_id IS NULL THEN
    RAISE EXCEPTION 'Debe iniciar sesión para reservar una entrega.';
  END IF;

  IF NOT public.is_approved_recycler(v_recycler_id) THEN
    RAISE EXCEPTION 'Solo los recicladores aprobados pueden reservar material.';
  END IF;

  SELECT * INTO v_listing
  FROM public.recyclable_material_listings
  WHERE id = p_listing_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'La publicación de material no existe.';
  END IF;

  IF v_listing.status <> 'disponible' THEN
    RAISE EXCEPTION 'Esta publicación ya no se encuentra disponible (estado actual: %).', v_listing.status;
  END IF;

  v_qr_code := 'ECO-PKP-' || upper(substr(md5(random()::text || clock_timestamp()::text), 1, 8));

  INSERT INTO public.recycler_pickups (
    listing_id,
    recycler_id,
    qr_code,
    qr_expires_at,
    status
  )
  VALUES (
    p_listing_id,
    v_recycler_id,
    v_qr_code,
    v_expires_at,
    'pendiente'
  )
  RETURNING id INTO v_pickup_id;

  RETURN json_build_object(
    'success', true,
    'pickup_id', v_pickup_id,
    'listing_id', p_listing_id,
    'qr_code', v_qr_code,
    'qr_expires_at', v_expires_at,
    'message', 'Recolección reservada exitosamente.'
  );
END;
$$;

ALTER FUNCTION "public"."reserve_material_listing"("p_listing_id" "uuid") OWNER TO "postgres";

