CREATE OR REPLACE FUNCTION "public"."switch_active_role"("p_role_code" "text") RETURNS json
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'auth'
    AS $$
DECLARE
  v_user_id uuid := auth.uid();
BEGIN
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Usuario no autenticado.';
  END IF;

  IF NOT EXISTS (SELECT 1 FROM user_roles WHERE profile_id = v_user_id AND role_code = p_role_code) THEN
    RAISE EXCEPTION 'El usuario no tiene asignado el rol %.', p_role_code;
  END IF;

  UPDATE profiles
  SET active_role = p_role_code,
      role_code = p_role_code
  WHERE id = v_user_id;

  RETURN json_build_object(
    'success', true,
    'active_role', p_role_code,
    'message', 'Rol activo actualizado exitosamente.'
  );
END;
$$;

ALTER FUNCTION "public"."switch_active_role"("p_role_code" "text") OWNER TO "postgres";

CREATE OR REPLACE FUNCTION "public"."sync_citizen_ecopoints_balance"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
declare
  v_reason_type text;
  v_delta       int;
begin
  select type into v_reason_type 
  from transaction_reasons 
  where code = NEW.reason_code;

  if v_reason_type = 'spend' then
    v_delta := -abs(NEW.points);
  else
    v_delta := abs(NEW.points);
  end if;

  -- Actualiza el saldo en la tabla citizens.
  -- Si ecopoints_balance pasa a ser menor a 0, la regla
  -- CHECK (ecopoints_balance >= 0) cancelará la inserción automáticamente.
  update citizens
  set ecopoints_balance = ecopoints_balance + v_delta
  where profile_id = NEW.citizen_id;

  return NEW;
end;
$$;

ALTER FUNCTION "public"."sync_citizen_ecopoints_balance"() OWNER TO "postgres";

CREATE OR REPLACE FUNCTION "public"."sync_listing_and_notify_on_pickup_change"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'auth'
    AS $$
DECLARE
  v_owner_id uuid;
  v_material_type text;
BEGIN
  SELECT owner_id, material_type
    INTO v_owner_id, v_material_type
  FROM public.recyclable_material_listings
  WHERE id = NEW.listing_id;

  -- Cuando se crea una orden pendiente, marca la oferta como reservada y avisa al ciudadano dueño
  IF TG_OP = 'INSERT' AND NEW.status = 'pendiente' THEN
    UPDATE public.recyclable_material_listings
    SET status = 'reservado',
        cancelled_at = NULL
    WHERE id = NEW.listing_id
      AND status = 'disponible';

    IF v_owner_id IS NOT NULL THEN
      INSERT INTO public.notifications (profile_id, title, body, type, data)
      VALUES (
        v_owner_id,
        'Recolección reservada',
        'Un reciclador ha tomado tu publicación de ' || COALESCE(v_material_type, 'material reciclable') || '.',
        'recoleccion_reservada',
        jsonb_build_object('listing_id', NEW.listing_id, 'pickup_id', NEW.id)
      );
    END IF;

  -- Cuando una orden pendiente se cancela, actualiza la oferta según quién originó la cancelación
  ELSIF TG_OP = 'UPDATE' AND OLD.status = 'pendiente' AND NEW.status = 'cancelado' THEN
    IF auth.uid() = v_owner_id THEN
      -- Si cancela el ciudadano dueño, la publicación queda cerrada como cancelada y se avisa al reciclador
      UPDATE public.recyclable_material_listings
      SET status = 'cancelado',
          cancelled_at = COALESCE(cancelled_at, now())
      WHERE id = NEW.listing_id
        AND status <> 'cancelado';

      INSERT INTO public.notifications (profile_id, title, body, type, data)
      VALUES (
        NEW.recycler_id,
        'Entrega cancelada por el ciudadano',
        'El ciudadano canceló la entrega de ' || COALESCE(v_material_type, 'material reciclable') || '.',
        'recoleccion_cancelada',
        jsonb_build_object('listing_id', NEW.listing_id, 'pickup_id', NEW.id)
      );
    ELSE
      -- Si cancela el reciclador, la publicación regresa a disponible en el mapa y se avisa al ciudadano
      UPDATE public.recyclable_material_listings
      SET status = 'disponible',
          cancelled_at = NULL
      WHERE id = NEW.listing_id
        AND status = 'reservado';

      IF v_owner_id IS NOT NULL THEN
        INSERT INTO public.notifications (profile_id, title, body, type, data)
        VALUES (
          v_owner_id,
          'Recolección cancelada',
          'El reciclador no pudo completar el retiro de ' || COALESCE(v_material_type, 'material reciclable') || '. Tu oferta volvió a estar disponible.',
          'recoleccion_cancelada',
          jsonb_build_object('listing_id', NEW.listing_id, 'pickup_id', NEW.id)
        );
      END IF;
    END IF;
  END IF;

  RETURN NEW;
END;
$$;

ALTER FUNCTION "public"."sync_listing_and_notify_on_pickup_change"() OWNER TO "postgres";

CREATE OR REPLACE FUNCTION "public"."sync_user_roles_on_profile_insert"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  INSERT INTO public.user_roles (profile_id, role_code)
  VALUES (NEW.id, NEW.role_code)
  ON CONFLICT (profile_id, role_code) DO NOTHING;

  INSERT INTO public.user_roles (profile_id, role_code)
  VALUES (NEW.id, 'citizen')
  ON CONFLICT (profile_id, role_code) DO NOTHING;

  RETURN NEW;
END;
$$;

ALTER FUNCTION "public"."sync_user_roles_on_profile_insert"() OWNER TO "postgres";

