CREATE OR REPLACE FUNCTION "public"."validate_and_credit_pickup"("p_pickup_id" "uuid", "p_scanned_qr" "text", "p_recycler_lat" numeric, "p_recycler_lng" numeric, "p_confirmed_volume_category" "text") RETURNS json
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  v_pickup record;
  v_listing record;
  v_recycler_loc geography;
  v_points_to_award int;
  v_multiplier int;
BEGIN
  -- A. Buscar la orden de recolección
  SELECT * INTO v_pickup FROM recycler_pickups WHERE id = p_pickup_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'La orden de recolección no existe.';
  END IF;

  -- B. Validar estado y código QR
  IF v_pickup.status <> 'pendiente' THEN
    RAISE EXCEPTION 'Esta entrega ya fue procesada o cancelada.';
  END IF;

  IF v_pickup.qr_code <> p_scanned_qr THEN
    RAISE EXCEPTION 'El código QR escaneado es inválido.';
  END IF;

  IF NOW() > v_pickup.qr_expires_at THEN
    RAISE EXCEPTION 'El código QR ha expirado.';
  END IF;

  -- C. Validar geolocalización (Distancia máxima permitida: 100 metros)
  SELECT * INTO v_listing FROM recyclable_material_listings WHERE id = v_pickup.listing_id;
  v_recycler_loc := ST_SetSRID(ST_MakePoint(p_recycler_lng, p_recycler_lat), 4326)::geography;

  IF ST_Distance(v_listing.location, v_recycler_loc) > 100 THEN
    RAISE EXCEPTION 'Ubicación no verificada: Debe estar a menos de 100m de la entrega.';
  END IF;

  -- D. Calcular puntos según categoría de volumen
  v_multiplier := CASE p_confirmed_volume_category
    WHEN 'alto' THEN 3
    WHEN 'medio' THEN 2
    ELSE 1
  END;
  v_points_to_award := 10 * v_multiplier;

  -- E. Actualizar estado de la recolección
  UPDATE recycler_pickups
  SET status = 'completado',
      geolocation_verified = true,
      confirmed_volume_category = p_confirmed_volume_category
  WHERE id = p_pickup_id;

  -- F. Marcar la publicación como completada
  UPDATE recyclable_material_listings
  SET status = 'completado'
  WHERE id = v_pickup.listing_id;

  -- G. Registrar la transacción de EcoPuntos (El trigger sync_citizen_ecopoints_balance sumará el saldo)
  INSERT INTO ecopoints_transactions (citizen_id, points, reason_code, pickup_id)
  VALUES (v_listing.owner_id, v_points_to_award, 'entrega_material', p_pickup_id);

  RETURN json_build_object(
    'success', true,
    'points_awarded', v_points_to_award,
    'message', 'Entrega validada y EcoPuntos acreditados exitosamente.'
  );
END;
$$;

ALTER FUNCTION "public"."validate_and_credit_pickup"("p_pickup_id" "uuid", "p_scanned_qr" "text", "p_recycler_lat" numeric, "p_recycler_lng" numeric, "p_confirmed_volume_category" "text") OWNER TO "postgres";

CREATE OR REPLACE FUNCTION "public"."validate_coupon_redemption"("p_code" "text") RETURNS json
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'auth'
    AS $$
DECLARE
  v_business_id uuid := auth.uid();
  v_redemption record;
  v_coupon record;
BEGIN
  IF v_business_id IS NULL THEN
    RAISE EXCEPTION 'Debe iniciar sesión como comercio para validar cupones.';
  END IF;

  IF NOT EXISTS (SELECT 1 FROM businesses WHERE profile_id = v_business_id) THEN
    RAISE EXCEPTION 'Solo los comercios autorizados pueden validar cupones.';
  END IF;

  SELECT * INTO v_redemption 
  FROM coupon_redemptions 
  WHERE code = upper(trim(p_code))
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Código de cupón no encontrado o inválido.';
  END IF;

  IF v_redemption.status = 'canjeado' THEN
    RAISE EXCEPTION 'Este cupón ya fue canjeado el %.', to_char(v_redemption.used_at, 'DD/MM/YYYY HH24:MI');
  END IF;

  IF v_redemption.status = 'expirado' THEN
    RAISE EXCEPTION 'Este cupón ha expirado.';
  END IF;

  SELECT * INTO v_coupon FROM coupons WHERE id = v_redemption.coupon_id;
  IF v_coupon.business_id <> v_business_id THEN
    RAISE EXCEPTION 'Este cupón pertenece a otro establecimiento comercial.';
  END IF;

  UPDATE coupon_redemptions
  SET status = 'canjeado',
      used_at = now(),
      validated_by = v_business_id
  WHERE id = v_redemption.id;

  RETURN json_build_object(
    'success', true,
    'coupon_title', v_coupon.title,
    'redemption_id', v_redemption.id,
    'used_at', now(),
    'message', 'Cupón validado y canjeado exitosamente.'
  );
END;
$$;

ALTER FUNCTION "public"."validate_coupon_redemption"("p_code" "text") OWNER TO "postgres";

