CREATE POLICY "Administrador EcoRuta gestiona todas las empresas" ON "public"."companies" TO "authenticated" USING ((EXISTS ( SELECT 1
   FROM "public"."profiles"
  WHERE (("profiles"."id" = "auth"."uid"()) AND ("profiles"."role_code" = 'admin'::"text")))));

CREATE POLICY "Administrador EcoRuta gestiona todos los comercios" ON "public"."businesses" TO "authenticated" USING ((EXISTS ( SELECT 1
   FROM "public"."profiles"
  WHERE (("profiles"."id" = "auth"."uid"()) AND ("profiles"."role_code" = 'admin'::"text")))));

CREATE POLICY "Administrador EcoRuta gestiona todos los recicladores" ON "public"."recyclers" TO "authenticated" USING ((EXISTS ( SELECT 1
   FROM "public"."profiles"
  WHERE (("profiles"."id" = "auth"."uid"()) AND ("profiles"."role_code" = 'admin'::"text")))));

CREATE POLICY "Administrador EcoRuta y Administrador de Empresa gestionan oper" ON "public"."operators" TO "authenticated" USING (("public"."is_admin"("auth"."uid"()) OR "public"."is_company_owner"("company_id", "auth"."uid"())));

CREATE POLICY "Administrador de empresa gestiona su propia empresa" ON "public"."companies" TO "authenticated" USING (("owner_profile_id" = "auth"."uid"()));

CREATE POLICY "Administrador de empresa y operadores gestionan recicladores vi" ON "public"."recyclers" TO "authenticated" USING (("public"."is_company_owner"("company_id", "auth"."uid"()) OR "public"."is_company_operator"("company_id", "auth"."uid"())));

CREATE POLICY "Choferes y recicladores leen sus rutas asignadas" ON "public"."routes" FOR SELECT TO "authenticated" USING ((("assigned_driver_id" = "auth"."uid"()) OR ("assigned_recycler_id" = "auth"."uid"()) OR (EXISTS ( SELECT 1
   FROM "public"."operators"
  WHERE (("operators"."profile_id" = "auth"."uid"()) AND ("operators"."company_id" = "routes"."company_id")))) OR (EXISTS ( SELECT 1
   FROM "public"."companies"
  WHERE (("companies"."id" = "routes"."company_id") AND ("companies"."owner_profile_id" = "auth"."uid"()))))));

CREATE POLICY "Ciudadanos agregan fotos a sus reportes" ON "public"."report_photos" FOR INSERT WITH CHECK ((EXISTS ( SELECT 1
   FROM "public"."reports"
  WHERE (("reports"."id" = "report_photos"."report_id") AND ("reports"."citizen_id" = "auth"."uid"())))));

CREATE POLICY "Ciudadanos cancelan recolecciones de sus ofertas" ON "public"."recycler_pickups" FOR UPDATE TO "authenticated" USING ((("status" = 'pendiente'::"text") AND (EXISTS ( SELECT 1
   FROM "public"."recyclable_material_listings" "l"
  WHERE (("l"."id" = "recycler_pickups"."listing_id") AND ("l"."owner_id" = "auth"."uid"())))))) WITH CHECK (("status" = 'cancelado'::"text"));

CREATE POLICY "Ciudadanos cancelan sus solicitudes pendientes" ON "public"."bulky_waste_requests" FOR UPDATE TO "authenticated" USING ((("auth"."uid"() = "citizen_id") AND ("status" = 'pendiente'::"text"))) WITH CHECK ((("auth"."uid"() = "citizen_id") AND ("status" = 'cancelado'::"text")));

