CREATE POLICY "Ciudadanos ven reciclador asignado a su entrega" ON "public"."recyclers" FOR SELECT TO "authenticated" USING ("public"."can_citizen_see_recycler"("profile_id", "auth"."uid"()));

CREATE POLICY "Ciudadanos ven recolecciones de sus ofertas" ON "public"."recycler_pickups" FOR SELECT TO "authenticated" USING ((EXISTS ( SELECT 1
   FROM "public"."recyclable_material_listings" "l"
  WHERE (("l"."id" = "recycler_pickups"."listing_id") AND ("l"."owner_id" = "auth"."uid"())))));

