CREATE POLICY "Ciudadanos ven sus capacitaciones completadas" ON "public"."educational_completions" FOR SELECT USING (("auth"."uid"() = "citizen_id"));

CREATE POLICY "Ciudadanos ven sus propias solicitudes de escombros" ON "public"."bulky_waste_requests" FOR SELECT TO "authenticated" USING (("auth"."uid"() = "citizen_id"));

