CREATE POLICY "Comercios gestionan sus propios cupones" ON "public"."coupons" USING (("business_id" = "auth"."uid"()));

CREATE POLICY "Comercios registran su perfil" ON "public"."businesses" FOR INSERT TO "authenticated" WITH CHECK (("auth"."uid"() = "profile_id"));

CREATE POLICY "Cualquiera lee empresas aprobadas y activas" ON "public"."companies" FOR SELECT USING ((("status" = 'aprobado'::"text") AND ("is_active" = true)));

CREATE POLICY "Despachadores y administradores de empresa gestionan rutas" ON "public"."routes" TO "authenticated" USING (((EXISTS ( SELECT 1
   FROM "public"."operators"
  WHERE (("operators"."profile_id" = "auth"."uid"()) AND ("operators"."company_id" = "routes"."company_id")))) OR (EXISTS ( SELECT 1
   FROM "public"."companies"
  WHERE (("companies"."id" = "routes"."company_id") AND ("companies"."owner_profile_id" = "auth"."uid"()))))));

CREATE POLICY "Empresas en autoregistro se insertan pendientes" ON "public"."companies" FOR INSERT TO "authenticated" WITH CHECK ((("status" = 'pendiente'::"text") AND ("owner_profile_id" = "auth"."uid"())));

CREATE POLICY "Empresas y Operadores gestionan solicitudes de escombros" ON "public"."bulky_waste_requests" TO "authenticated" USING (((EXISTS ( SELECT 1
   FROM "public"."companies"
  WHERE ((("bulky_waste_requests"."company_id" IS NULL) OR ("bulky_waste_requests"."company_id" = "companies"."id")) AND ("companies"."owner_profile_id" = "auth"."uid"())))) OR (EXISTS ( SELECT 1
   FROM "public"."operators"
  WHERE (("operators"."profile_id" = "auth"."uid"()) AND (("bulky_waste_requests"."company_id" IS NULL) OR ("bulky_waste_requests"."company_id" = "operators"."company_id"))))) OR (EXISTS ( SELECT 1
   FROM "public"."profiles"
  WHERE (("profiles"."id" = "auth"."uid"()) AND ("profiles"."role_code" = 'admin'::"text"))))));

